35: func (m *monitor) Started(ctx context.Context, evt *event.CommandStartedEvent) {
36: 	hostname, port := peerInfo(evt)
37: 
38: 	attrs := []attribute.KeyValue{semconv.DBSystemMongoDB}
39: 
40: 	attrs = appendOpNameAttrs(attrs, evt.CommandName)
41: 	attrs = appendDBNamespace(attrs, evt.DatabaseName)
42: 	attrs = appendNetworkPort(attrs, port)
43: 	attrs = appendNetworkHost(attrs, hostname)
44: 	attrs = appendNetworkAddress(attrs, net.JoinHostPort(hostname, strconv.Itoa(port)))
45: 	attrs = appendNetworkTransport(attrs)
46: 
47: 	if !m.cfg.CommandAttributeDisabled {
48: 		attrs = appendDBStatement(attrs, sanitizeCommand(evt.Command))
49: 	}
50: 
51: 	var spanName string
52: 	if collection, err := extractCollection(evt); err == nil && collection != "" {
53: 		spanName = collection + "."
54: 
55: 		attrs = appendCollection(attrs, collection)
56: 	}
57: 
58: 	spanName += evt.CommandName
59: 	opts := []trace.SpanStartOption{
60: 		trace.WithSpanKind(trace.SpanKindClient),
61: 		trace.WithAttributes(attrs...),
62: 	}
63: 	_, span := m.cfg.Tracer.Start(ctx, spanName, opts...)
64: 	key := spanKey{
65: 		ConnectionID: evt.ConnectionID,
66: 		RequestID:    evt.RequestID,
67: 	}
68: 	m.Lock()
69: 	m.spans[key] = span
70: 	m.Unlock()
71: }
