81: func (m *monitor) Finished(evt *event.CommandFinishedEvent, err error) {
82: 	key := spanKey{
83: 		ConnectionID: evt.ConnectionID,
84: 		RequestID:    evt.RequestID,
85: 	}
86: 	m.Lock()
87: 	span, ok := m.spans[key]
88: 	if ok {
89: 		delete(m.spans, key)
90: 	}
91: 	m.Unlock()
92: 	if !ok {
93: 		return
94: 	}
95: 
96: 	if err != nil {
97: 		span.SetStatus(codes.Error, err.Error())
98: 	}
99: 
100: 	span.End()
101: }
