110: // extractCollection extracts the collection for the given mongodb command event.
111: // For CRUD operations, this is the first key/value string pair in the bson
112: // document where key == "<operation>" (e.g. key == "insert").
113: // For database meta-level operations, such a key may not exist.
114: func extractCollection(evt *event.CommandStartedEvent) (string, error) {
115: 	elt, err := evt.Command.IndexErr(0)
116: 	if err != nil {
117: 		return "", err
118: 	}
119: 	if key, err := elt.KeyErr(); err == nil && key == evt.CommandName {
120: 		var v bson.RawValue
121: 		if v, err = elt.ValueErr(); err != nil || v.Type != bson.TypeString {
122: 			return "", err
123: 		}
124: 		return v.StringValue(), nil
125: 	}
126: 	return "", errors.New("collection name not found")
127: }
