130: func NewMonitor(opts ...Option) *event.CommandMonitor {
131: 	cfg := newConfig(opts...)
132: 	m := &monitor{
133: 		spans: make(map[spanKey]trace.Span),
134: 		cfg:   cfg,
135: 	}
136: 	return &event.CommandMonitor{
137: 		Started:   m.Started,
138: 		Succeeded: m.Succeeded,
139: 		Failed:    m.Failed,
140: 	}
141: }
