143: func peerInfo(evt *event.CommandStartedEvent) (hostname string, port int) {
144: 	hostname = evt.ConnectionID
145: 	port = 27017
146: 	if idx := strings.IndexByte(hostname, '['); idx >= 0 {
147: 		hostname = hostname[:idx]
148: 	}
149: 	if idx := strings.IndexByte(hostname, ':'); idx >= 0 {
150: 		port = func(p int, e error) int { return p }(strconv.Atoi(hostname[idx+1:]))
151: 		hostname = hostname[:idx]
152: 	}
153: 	return hostname, port
154: }

